out = {}
total = 0
for name in repo.list("data"):
    if name.endswith(".txt"):
        content = repo.read("data/" + name)
        # count lines including blanks; treat trailing newline as not adding an extra empty line
        n = len(content.split("\n"))
        if content.endswith("\n"):
            n -= 1
        out[name] = n
        total += n
out["total"] = total
return out
